hooks.command:
node -e "
const { DatabaseSync } = require('node:sqlite');
const path = require('path');
const os = require('os');
const dataDir = process.env.DATA_DIR || path.join(os.homedir(), 'Library/Application Support/apotheosis');
try {
  const db = new DatabaseSync(path.join(dataDir, 'apotheosis.db'), { readOnly: true });
  const d = new Date();
  const today = [d.getFullYear(), String(d.getMonth() + 1).padStart(2, '0'), String(d.getDate()).padStart(2, '0')].join('-');
  const row = db.prepare('SELECT id FROM standups WHERE date = ?').get(today);
  if (!row && d.getDay() > 0 && d.getDay() < 6) process.stdout.write('[[reminder: you haven\'t logged /standup yet today]]\n');
  db.close();
} catch (e) { /* db not ready yet */ }
" 2>/dev/null || true
